-- Don Bernardo exact compound sales identities, generated from the certified 2026-08-20 prewrite.
CREATE TABLE IF NOT EXISTS public.agora_sales_variant_mappings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  connection_id uuid NOT NULL REFERENCES public.pos_connections(id) ON DELETE CASCADE,
  provider_product_id text NOT NULL,
  sale_format_id text NOT NULL,
  provider_product_name text NOT NULL,
  provider_sale_format_name text NOT NULL,
  winerim_wine_id text NOT NULL,
  format_type text NOT NULL CHECK (format_type IN ('BOTTLE','GLASS','MAGNUM','OTHER')),
  match_method text NOT NULL,
  status text NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('CONFIRMED','BLOCKED','REJECTED')),
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(connection_id, provider_product_id, sale_format_id)
);
GRANT ALL ON public.agora_sales_variant_mappings TO service_role;
ALTER TABLE public.agora_sales_variant_mappings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.agora_sales_variant_mappings FROM anon, authenticated;
CREATE INDEX IF NOT EXISTS idx_agora_sales_variant_mappings_lookup ON public.agora_sales_variant_mappings(connection_id, provider_product_id, sale_format_id) WHERE status='CONFIRMED';

ON CONFLICT (connection_id,provider_product_id,sale_format_id) DO UPDATE SET
 provider_product_name=EXCLUDED.provider_product_name, provider_sale_format_name=EXCLUDED.provider_sale_format_name, winerim_wine_id=EXCLUDED.winerim_wine_id, format_type=EXCLUDED.format_type, match_method=EXCLUDED.match_method, status=EXCLUDED.status, evidence=EXCLUDED.evidence, updated_at=now();

DO $guard$ DECLARE p int; s int; BEGIN
 SELECT count(*) INTO p FROM public.agora_sales_variant_mappings WHERE connection_id='a700d425-9194-4758-95ff-7fee86419e14'::uuid AND status='CONFIRMED';
 SELECT count(*) INTO s FROM public.agora_sales_variant_mappings WHERE connection_id='79280cb8-0fe7-4a57-93a4-04172205ac70'::uuid AND status='CONFIRMED';
 IF p<>119 OR s<>187 THEN RAISE EXCEPTION 'DON_BERNARDO_COMPOUND_MAPPING_COUNT_MISMATCH p=% s=%',p,s; END IF;
END $guard$;
